    // -----------------------------
    // Product model
    // -----------------------------
    static class Product {
        int id;
        String name, category, brand, description;
        double mrp, salePrice, rating;
        int reviews;
        String[] images;

        Product(int id, String name, String category, String brand,
                double mrp, double salePrice, double rating, int reviews,
                String description, String... images) {
            this.id = id;
            this.name = name;
            this.category = category;
            this.brand = brand;
            this.mrp = mrp;
            this.salePrice = salePrice;
            this.rating = rating;
            this.reviews = reviews;
            this.description = description;
            this.images = images;
        }

        int discount() {
            return (int)Math.round((mrp - salePrice) * 100.0 / mrp);
        }
    }

    static class Order {
        String id, customer, phone, address, date, status;
        List<Product> products;
        double total;

        Order(String id, String customer, String phone, String address,
              List<Product> products, double total) {
            this.id = id;
            this.customer = customer;
            this.phone = phone;
            this.address = address;
            this.products = new ArrayList<>(products);
            this.total = total;
            this.date = new Date().toString();
            this.status = "Order Confirmed";
        }
    }

