    // -----------------------------
    // Server
    // -----------------------------
    public static void main(String[] args) throws Exception {
        if (PRODUCTS.isEmpty()) seedProducts();
        HttpServer server = HttpServer.create(new InetSocketAddress(8080), 0);
        server.createContext("/", EquiGraStore::handle);
        server.setExecutor(Executors.newCachedThreadPool());
        server.start();
        System.out.println("EquiGra Store running at http://localhost:8080");
        System.out.println("Keep this terminal open while using the website.");
    }

    static void handle(HttpExchange ex) throws IOException {
        try {
            String path = ex.getRequestURI().getPath();
            Map<String,String> q = queryParams(ex.getRequestURI().getRawQuery());
            if (ex.getRequestMethod().equalsIgnoreCase("POST")) {
                String body = readBody(ex);
                q.putAll(queryParams(body));
            }
            String sid = sessionId(ex);

            if (path.equals("/logo.jpg")) {
                sendLogo(ex);
                return;
            }

            if (path.equals("/style.css")) {
                send(ex, 200, "text/css; charset=UTF-8", css());
                return;
            }

            if (path.equals("/app.js")) {
                send(ex, 200, "application/javascript; charset=UTF-8", js());
                return;
            }

            if (path.equals("/logout")) {
                ex.getResponseHeaders().add("Set-Cookie", "EQ_SESSION=" + UUID.randomUUID() + "; Path=/");
                redirect(ex, "/");
                return;
            }

            if (path.equals("/login") && ex.getRequestMethod().equalsIgnoreCase("POST")) {
                String email = q.getOrDefault("email", "").trim();
                String password = q.getOrDefault("password", "");
                if (!email.isEmpty() && !password.isEmpty()) {
                    USERS.putIfAbsent(email, password);
                    ex.getResponseHeaders().add("Set-Cookie", "EQ_USER=" + URLEncoder.encode(email, StandardCharsets.UTF_8) + "; Path=/");
                    redirect(ex, "/?welcome=1&email=" + URLEncoder.encode(email, StandardCharsets.UTF_8));
                } else {
                    redirect(ex, "/?login=1");
                }
                return;
            }

            if (path.equals("/add")) {
                int id = intVal(q.get("id"), 1);
                cart(sid).add(id);
                redirect(ex, "/cart");
                return;
            }

            if (path.equals("/remove")) {
                int id = intVal(q.get("id"), 1);
                cart(sid).remove((Integer)id);
                redirect(ex, "/cart");
                return;
            }

            if (path.equals("/clear-cart")) {
                cart(sid).clear();
                redirect(ex, "/cart");
                return;
            }

            if (path.equals("/place-order") && ex.getRequestMethod().equalsIgnoreCase("POST")) {
                String user = currentUser(ex);
                if (user == null) {
                    redirect(ex, "/?login=1");
                    return;
                }
                List<Product> items = cartProducts(sid);
                if (items.isEmpty()) {
                    redirect(ex, "/cart");
                    return;
                }
                String name = q.getOrDefault("name", "EquiGra Customer");
                String phone = q.getOrDefault("phone", "");
                String address = q.getOrDefault("address", "");
                double total = total(items);
                String oid = "EQ" + (100000 + new Random().nextInt(900000));
                Order order = new Order(oid, name, phone, address, items, total);
                ORDERS.computeIfAbsent(user, k -> new ArrayList<>()).add(order);
                cart(sid).clear();
                redirect(ex, "/orders?placed=" + oid);
                return;
            }

            String user = currentUser(ex);
            String html;

            if (path.equals("/cart")) {
                html = page("Your Cart", cartPage(sid, user));
            } else if (path.equals("/orders")) {
                html = page("My Orders", ordersPage(user, q.get("placed")));
            } else if (path.equals("/product")) {
                int id = intVal(q.get("id"), 1);
                Product p = product(id);
                html = page(p == null ? "Product" : p.name, p == null ? notFound() : productPage(p, sid, user));
            } else if (path.equals("/category")) {
                html = page("Category", listingPage(q.getOrDefault("name", "All"), "", sid, user));
            } else if (path.equals("/search")) {
                html = page("Search", listingPage("Search results", q.getOrDefault("q", ""), sid, user));
            } else if (path.equals("/checkout")) {
                html = page("Checkout", checkoutPage(sid, user));
            } else {
                String home = homePage(q.getOrDefault("view", "home"), q.getOrDefault("q", ""), sid, user);
                if (q.get("welcome") != null && user != null) home = welcomeBanner(user) + home;
                if (q.get("login") != null) home = "<div class='login-alert'>Please sign in to continue.</div>" + home;
                html = page("EquiGra | Premium Shopping", home);
            }

            send(ex, 200, "text/html; charset=UTF-8", html);
        } catch (Exception e) {
            e.printStackTrace();
            send(ex, 500, "text/plain; charset=UTF-8", "EquiGra server error: " + e.getMessage());
        }
    }

